-- Phase 3 (sharing, face search, downloads):
-- 1. activity_events.source (share|owner); share_id is null exactly for owner downloads. The
--    table is partitioned: ALTERs on the parent apply to every partition.
-- 2. files: upload_part_bytes (the plan an upload was created with), client_upload_id (idempotent
--    POST /uploads/init, unique per owner), web_size_bytes (size of the web download variant).
-- 3. folders.face_index_informed_at, required while face indexing is on (PDPA checklist).
-- 4. face_deletions ("ขอลบใบหน้าของฉัน", counts only) and faces.deletion_id.
-- 5. consents: exactly one of viewer_id/anon_id, one current consent per share, viewer or session
--    and version (partial unique indexes), withdrawn_at >= accepted_at.
-- 6. share_daily_stats (per-share rollup for GET /shares/:id/stats), shares (owner_id, id) list
--    index, face_feedback created_at index, zip_jobs.url_issued_at.
CREATE TYPE "public"."activity_source" AS ENUM('share', 'owner');--> statement-breakpoint
CREATE TABLE "face_deletions" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7() NOT NULL,
	"photographer_id" uuid NOT NULL,
	"share_id" uuid NOT NULL,
	"faces_matched" integer NOT NULL,
	"faces_deleted" integer,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"completed_at" timestamp with time zone,
	CONSTRAINT "face_deletions_id_photographer_unique" UNIQUE("id","photographer_id"),
	CONSTRAINT "face_deletions_counts_nonnegative" CHECK ("face_deletions"."faces_matched" >= 0 AND ("face_deletions"."faces_deleted" IS NULL OR "face_deletions"."faces_deleted" >= 0)),
	CONSTRAINT "face_deletions_completed_has_count" CHECK (("face_deletions"."completed_at" IS NULL) = ("face_deletions"."faces_deleted" IS NULL))
);
