-- Backfills (hand-written), before the indexes and checks below that need them.
-- Open uploads get the part size multipartPlan gives with the default UPLOAD_PART_BYTES (16 MiB):
-- max(16 MiB, the smallest whole MiB that fits 10,000 parts), at most 5 GiB. An upload started
-- under another UPLOAD_PART_BYTES fails its complete (UPLOAD_PARTS_INVALID) and is uploaded again.
UPDATE "files" SET "upload_part_bytes" = GREATEST(16777216, LEAST(5368709120, CEIL(CEIL("size_bytes" / 10000.0) / 1048576.0)::bigint * 1048576)) WHERE "upload_id" IS NOT NULL AND "upload_part_bytes" IS NULL;--> statement-breakpoint
-- Face indexing without a recorded confirmation is turned off rather than given a made-up
-- confirmation; the photographer confirms again to turn it back on. faces.expire.daily deletes
-- the faces of files no active index covers any more.
UPDATE "folders" SET "face_index_enabled" = false WHERE "face_index_enabled" AND ("face_index_informed_at" IS NULL OR "face_index_expires_at" IS NULL);--> statement-breakpoint
-- A consent belongs to the signed-in viewer when both ids were stored.
UPDATE "consents" SET "anon_id" = NULL WHERE "viewer_id" IS NOT NULL AND "anon_id" IS NOT NULL;--> statement-breakpoint
-- Of duplicate current consents, the newest stays current; the others are withdrawn.
UPDATE "consents" AS "c" SET "withdrawn_at" = GREATEST(now(), "c"."accepted_at") WHERE "c"."withdrawn_at" IS NULL AND EXISTS (SELECT 1 FROM "consents" AS "d" WHERE "d"."withdrawn_at" IS NULL AND "d"."share_id" = "c"."share_id" AND "d"."policy_version" = "c"."policy_version" AND "d"."viewer_id" IS NOT DISTINCT FROM "c"."viewer_id" AND "d"."anon_id" IS NOT DISTINCT FROM "c"."anon_id" AND ("d"."accepted_at", "d"."id") > ("c"."accepted_at", "c"."id"));--> statement-breakpoint
UPDATE "consents" SET "withdrawn_at" = "accepted_at" WHERE "withdrawn_at" < "accepted_at";--> statement-breakpoint
